      <div className="bg-[#1f2937]/95 backdrop-blur-md px-4 py-3 rounded-2xl border border-white/10 shadow-2xl">
        <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1.5">{payload[0].payload.name} Statistics</p>
