      <BottomSheet isOpen={activeDetail !== null} onClose={() => setActiveDetail(null)}>
        {activeDetail === 'yield' && <YieldDetail />}
        {activeDetail === 'fees' && <FeesDetail />}
        {activeDetail === 'lending' && <LendingDetail />}
      </BottomSheet>
    </div>
  );
};

